// 逐字转换(纯函数,无状态;调用方自行 memo)
export function lingqiToSimp(str) {
  if (!str) { return ''; }
  let out = '';
  for (const ch of `${str}`) { out += LINGQI_T2S[ch] || ch; }
  return out;
}
